const artifactBase=location.hostname==='symphonia-dev-488613.web.app'?'https://symphonia-evaluation-20260926-h4znkmen4a-nw.a.run.app/':'';
let study;
const $=id=>document.getElementById(id);
const text=(tag,value,cls)=>{const e=document.createElement(tag);e.textContent=value;if(cls)e.className=cls;return e};
const percent=x=>typeof x==='number'?(100*x).toFixed(1)+'%':'—';
const labels={'pilot_preparation':'Preparing and validating the pilot','evaluator_calibration':'Validating the evaluators','evaluator_validation_failed':'Evaluator validation needs revision','pilot_generation':'Generating validated pilot panels','pilot_experiment_A':'Running fixed-judgment experiments','pilot_robustness':'Running pilot robustness checks','pilot_experiment_B':'Running responsive-participant experiments','pilot_complete':'Pilot complete','main_generation':'Generating independent main-study scenarios','main_experiment_A':'Running the main study','main_map_complete':'Main study in progress','stopped':'Execution paused at a recorded failure','experiments_finished_analysis_pending':'Experiment execution finished'};
function runs(){const query=$('search').value.toLowerCase();const rows=study.runs.filter(r=>JSON.stringify(r).toLowerCase().includes(query));$('run-rows').replaceChildren(...rows.slice(0,500).map(r=>{const tr=document.createElement('tr');tr.title=r.run_id;for(const v of [r.map_id,r.method,r.panel_size,r.words,r.track.replaceAll('_',' '),percent(r.metrics.critical_claim_strict_fidelity),r.status])tr.append(text('td',String(v)));return tr}));$('run-count').textContent=rows.length?`${rows.length} matching runs${rows.length>500?' · showing the first 500; complete records are in the download':''}.`:'No experiment results yet. Pilot preparation is recorded separately.';}
function render(d){study=d;$('status').textContent=labels[d.status.stage]||d.status.stage.replaceAll('_',' ');$('status-detail').textContent=d.status.error||`${d.model_calls} saved model calls · ${d.failed_model_calls} failed model calls · ${d.completed_runs} completed experiment runs.`;$('stats').replaceChildren(...[[d.completed_runs,'completed experiment runs'],[d.validated_panels,'validated synthetic panels'],[d.failed_runs,'failed experiment runs'],['$'+d.cost_usd.toFixed(2),'recorded model cost']].map(([value,label])=>{const div=text('div','','stat');div.append(text('strong',value),text('span',label));return div}));$('coverage').replaceChildren(...d.coverage.map(x=>{const div=document.createElement('div');div.append(text('span',x.name),text('span',x.status,'badge'+(['complete','passed'].includes(x.status)?' good':'')));return div}));$('calibration').replaceChildren();if(d.calibration){const img=document.createElement('img');img.src=artifactBase+'evaluator-validation.svg?t='+d.updated_at;img.alt='Evaluator sensitivity and false-positive rates against acceptance boundaries';img.className='plot';$('calibration').append(img);}else $('calibration').append(text('p','Evaluator results are not available yet.','empty'));
const names={'critical_claim_strict_fidelity':'Consequential claim fidelity','false_consensus_rate':'False-consensus rate'};$('effects').className='effect';$('effects').replaceChildren(...Object.entries(names).map(([key,name])=>{const div=document.createElement('div'),a=d.analyses[key];div.append(text('h3',name));if(a&&a.ci95){div.append(text('strong',(100*a.effect).toFixed(1)+' percentage points'),text('span',`95% CI ${(100*a.ci95[0]).toFixed(1)} to ${(100*a.ci95[1]).toFixed(1)} · ${a.maps} independent maps · ${a.phase}`),text('p',`Holm-adjusted p = ${a.p_holm.toPrecision(3)}. ${a.phase==='pilot'?'Exploratory pilot estimate.':''}`));}else div.append(text('p','Awaiting enough completed paired scenarios.','empty'));return div}));
const figNames=['Information loss by stage','Fidelity under compression','Disagreement and uncertainty','Consequential minority evidence','Robustness and mechanism'];$('figure-list').replaceChildren(...figNames.map((name,i)=>{const div=text('article','','figure');div.append(text('h3',`${i+1}. ${name}`));const key='figure-'+(i+1);if(d.figures.includes(key)){const img=document.createElement('img');img.src=artifactBase+key+'.svg?t='+d.updated_at;img.alt=name;img.className='plot';div.append(img);const a=text('a','Download SVG');a.href=artifactBase+key+'.svg';a.download=key+'.svg';div.append(a);}else div.append(text('p','This analysis has not produced a measured figure yet.','empty'));return div}));$('limitations').replaceChildren(...d.limitations.map(l=>text('li',l)));$('scenarios').replaceChildren(...d.scenarios.map(s=>{const div=text('div','','scenario');div.append(text('small',`${s.id} · ${s.setting} · ${s.claims} claims · ${s.phase}`),text('p',s.question));return div}));$('updated').textContent='Record updated '+new Date(d.updated_at*1000).toLocaleString();runs();}
async function refresh(){try{const r=await fetch(artifactBase+'data.json',{cache:'no-store'});if(!r.ok)throw Error('Study record could not be loaded.');render(await r.json());}catch(e){$('status').textContent='Study record unavailable';$('status-detail').textContent=e.message;}}
document.querySelectorAll('[data-tab]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==b.dataset.tab);}));$('search').addEventListener('input',runs);$('refresh').addEventListener('click',refresh);refresh();

document.querySelectorAll('a[download],a[href="data.json"]').forEach(a=>a.href=artifactBase+a.getAttribute('href'));
setInterval(()=>{if(!document.hidden)refresh()},60000);
